from pathlib import Path
import json,subprocess,hashlib
from datetime import datetime,timezone
from scripts.vertex_concept_review import _call_model,MODEL
r=Path('catalog/source-facts-escalation-v1');targets=list(map(json.loads,(r/'missing-targets-v1.jsonl').read_text().splitlines()));subjects=[{k:x['endpoint_snapshot'][k] for k in ['card_id','name','set_code','collector_number','language']} for x in targets]
prompt='''Research publisher evidence for these source-card asset gaps using Google Search. Search primary pokemon-card.com pages. Return JSON with leads grouped by exact release and collector number, explicit URLs, source date, uncertainty, and why a superficially similar same-name card is NOT an exact release match. Do not infer missing scans, completed sales, foil or price. Official Morpeko V-UNION page 40208 combines S8b 056/184,057/184,058/184,059/184: identify multipart scope rather than substitute a complete image for one part. Official Mew page 50574 uses MF and may not match M6A G/R. Verify the M6a release date versus research date 2026-10-03. Missing asset records are research inputs, not established publisher identity. Do not approve catalog identity or label number readings. Do not use secondary marketplace titles as conclusive metadata. Subjects:\n'''+json.dumps(subjects,ensure_ascii=False)
req=dict(contents=[dict(role='user',parts=[dict(text=prompt)])],tools=[dict(googleSearch={})],generationConfig=dict(maxOutputTokens=6000))
protocol=dict(schema='pokemon.missing-source-grounded-research.v1',model=MODEL,requested_at=datetime.now(timezone.utc).isoformat(),catalog_context_visible=True,prior_research_leads_visible=True,prior_blind_verdicts_visible=False,google_search_grounding_enabled=True,scope='Research leads only; not blind pixel inspection, catalog correction, identity or price approval',targets_sha256=hashlib.sha256((r/'missing-targets-v1.jsonl').read_bytes()).hexdigest(),prompt=prompt,prompt_sha256=hashlib.sha256(prompt.encode()).hexdigest())
(r/'grounded-research-protocol-v1.json').write_text(json.dumps(protocol,ensure_ascii=False,indent=2)+'\n')
token=subprocess.check_output(['gcloud','auth','print-access-token'],text=True,stderr=subprocess.DEVNULL).strip();response=_call_model('pivota-staging','global',token,req)
assert response['modelVersion']==MODEL
(r/'grounded-research-response-v1.json').write_text(json.dumps(dict(response=response,completed_at=datetime.now(timezone.utc).isoformat(),protocol_sha256=hashlib.sha256((r/'grounded-research-protocol-v1.json').read_bytes()).hexdigest()),ensure_ascii=False,indent=2)+'\n')
print(json.dumps(dict(model=response['modelVersion'],finish=[c.get('finishReason') for c in response.get('candidates',[])],grounding_metadata_present=any('groundingMetadata' in c for c in response.get('candidates',[])))))
